  // Parametric shared lattice for "The Starspun Weave" (18 asymmetric spokes × 6 orb rings = 108 deformable cells,
  // with all 16 stars of The Thief constellation pinned directly to web silk intersections).
  const STARSPUN_WEB_SPEC = (() => {
    const hub = { x: 50, y: 47 };
    const ringBaseR = [8.8, 13.6, 19.6, 26.2, 33.4, 40.8];
    const spokeSpecs = [
      { ang: -175, rMax: 45, rOv: { 2: 20.0 } },            // 0:  Star 5 (Left Elbow)
      { ang: -160, rMax: 47, rOv: { 4: 35.5 } },            // 1:  Star 4 (Left Dagger Tip)
      { ang: -136, rMax: 44, rOv: { 1: 13.2 } },            // 2:  Star 0 (Brightest Thief Nexus)
      { ang: -124, rMax: 45, rOv: { 3: 25.4 } },            // 3:  Star 2 (Hood Front Tip)
      { ang: -110, rMax: 45, rOv: { 2: 19.2 } },            // 4:  Star 3 (Hood Collar)
      { ang: -95, rMax: 44, rOv: { 4: 31.2 } },            // 5:  Star 1 (Hood Peak)
      { ang: -72, rMax: 43, rOv: {} },                     // 6:  Upper-right bridge spoke
      { ang: -52, rMax: 47, rOv: { 4: 35.6 } },            // 7:  Star 10 (Sweeping Cloak Crest)
      { ang: -34, rMax: 43, rOv: { 0: 8.8 } },             // 8:  Star 11 (Inner Cloak Top)
      { ang: -8, rMax: 45, rOv: { 2: 18.0 } },            // 9:  Star 12 (Inner Cloak Right)
      { ang: 19, rMax: 46, rOv: { 4: 30.0 } },            // 10: Star 13 (Trailing Cape Edge)
      { ang: 38, rMax: 43, rOv: { 1: 14.0 } },            // 11: Star 14 (Inner Cloak Bottom)
      { ang: 52, rMax: 45, rOv: { 3: 26.2 } },            // 12: Star 15 (Rear Boot / Dagger)
      { ang: 70, rMax: 41, rOv: { 0: 9.0 } },             // 13: Star 7 (Waist / Hip)
      { ang: 96, rMax: 43, rOv: { 4: 29.2 } },            // 14: Star 9 (Forward Foot)
      { ang: 118, rMax: 43, rOv: {} },                     // 15: Lower-left bridge spoke
      { ang: 140, rMax: 47, rOv: { 3: 26.6 } },            // 16: Star 8 (Bent Forward Knee)
      { ang: 160, rMax: 45, rOv: { 3: 26.6 } }             // 17: Star 6 (Lower-Left Hand)
    ];

    const grid = spokeSpecs.map((sp, sIdx) => {
      const rad = (sp.ang * Math.PI) / 180;
      const cos = Math.cos(rad);
      const sin = Math.sin(rad);
      const pts = ringBaseR.map((baseR, rIdx) => {
        const wobble = Math.sin(sIdx * 2.1 + rIdx * 1.4) * 0.65;
        const r = sp.rOv[rIdx] != null ? sp.rOv[rIdx] : (baseR + wobble);
        return {
          x: hub.x + cos * r,
          y: hub.y + sin * r,
          r,
          s: sIdx,
          ring: rIdx
        };
      });
      const anchor = { x: hub.x + cos * sp.rMax, y: hub.y + sin * sp.rMax };
      return { angDeg: sp.ang, angRad: rad, cos, sin, rMax: sp.rMax, pts, anchor };
    });

    // Exact 16-star topology of The Thief constellation pinned to (spokeIdx, ringIdx) web intersections
    const thiefStars = [
      { s: 2, r: 1, mag: 1.72, name: 'nexus' },
      { s: 5, r: 4, mag: 1.24, name: 'hoodPeak' },
      { s: 3, r: 3, mag: 1.06, name: 'hoodTip' },
      { s: 4, r: 2, mag: 0.96, name: 'hoodChin' },
      { s: 1, r: 4, mag: 1.22, name: 'daggerTip' },
      { s: 0, r: 2, mag: 1.00, name: 'elbowL' },
      { s: 17, r: 3, mag: 1.12, name: 'handL' },
      { s: 13, r: 0, mag: 1.12, name: 'waist' },
      { s: 16, r: 3, mag: 1.22, name: 'kneeF' },
      { s: 14, r: 4, mag: 1.18, name: 'footF' },
      { s: 7, r: 4, mag: 1.30, name: 'cloakCrest' },
      { s: 8, r: 0, mag: 0.98, name: 'cloakInTop' },
      { s: 9, r: 2, mag: 1.08, name: 'cloakInR' },
      { s: 10, r: 4, mag: 1.26, name: 'cloakHem' },
      { s: 11, r: 1, mag: 1.02, name: 'cloakInBot' },
      { s: 12, r: 3, mag: 1.14, name: 'rearBoot' }
    ];

    const thiefEdges = [
      [0, 3], [3, 1], [1, 2], [2, 0],           // Hood spire
      [0, 4],                                   // Outstretched dagger arm
      [0, 5], [5, 6],                           // Forward crouch forearm
      [0, 7], [7, 8], [8, 9],                   // Torso -> bent leg -> foot
      [0, 10], [10, 13],                        // Sweeping cloak crest & hem
      [0, 11], [11, 12], [12, 14], [14, 11],    // Back cloak dagger-fold triangle
      [14, 15]                                  // Trailing boot/blade point
    ];

    return { hub, ringBaseR, grid, thiefStars, thiefEdges };
  })();

