  function getSetStageTitle(setKey, stageIdx, lang = 'ru') {
    const idx = Math.max(0, Math.min(4, Number(stageIdx ?? 2)));
    const l = lang === 'en' ? 'en' : 'ru';
    const perSet = SET_STAGE_TITLES[setKey];
    if (perSet && perSet[idx]) return perSet[idx][l] || perSet[idx].en || perSet[idx].ru;
    const base = SIGIL_STAGES[idx] || SIGIL_STAGES[2];
    return base[l] || base.en || '';
  }

