  function getRelicVariantStages(relic) {
    const tiers = (relic && relic.tooltip && relic.tooltip.tiers) || [];
    if (relic && relic.omitMidVariant) return [0, 4];
    if (tiers.length > 0 && tiers.length < 3) return [0, 4];
    return [0, 2, 4];
  }

  function evalStageParam(spec, stage) {
    if (spec == null) return '?';
    if (typeof spec === 'number') return spec;
    if (Array.isArray(spec)) {
      const a = Number(spec[0]), b = Number(spec[1]);
      return Math.round(a + ((b - a) * Math.max(0, Math.min(4, stage))) / 4);
    }
    return spec;
  }

