            cg.addColorStop(0, `rgba(255, 124, 30, ${(alpha * 0.62 * pulseGlow).toFixed(3)})`);
            cg.addColorStop(0.55, `rgba(225, 42, 10, ${(alpha * 0.28).toFixed(3)})`);
