            ctx.closePath();
            ctx.fill();

            ctx.fillStyle = pt.color;
            ctx.beginPath();
            ctx.arc(-pt.size * 0.08, 0, pt.size * 0.48 * pulseGlow, 0, Math.PI * 2);
            ctx.fill();
            ctx.fillStyle = '#ffdf78';
