                ctx.lineTo(0.95 * s, -0.95 * s);
                ctx.moveTo(0.50 * s, -0.95 * s);
                ctx.lineTo(0.95 * s, -0.95 * s);
                ctx.lineTo(0.95 * s, -0.50 * s);
