      setZoom: (z) => { state.zoom = z; applyLayoutState(); },
      setStage: (s) => { state.stage = s; applyLayoutState(); refreshStageVariants(); },
      setCardStage: (key, s) => setCardStage(key, s, true),
      getCardStage: (key) => getCardStage(key),
      setBackdrop: (bg) => { state.backdrop = bg; applyLayoutState(); },
      setLang: (l) => { state.lang = l; applyLayoutState(); refreshLabels(); },
      setLabels: (v) => { state.labels = !!v; applyLayoutState(); },
      setCaliper: (v) => { state.caliper = !!v; applyLayoutState(); },
      setContextOpen: (v) => { state.contextOpen = !!v; applyLayoutState(); renderContextPreview(); },
