  const V2_SHADOW_SVG_CACHE = new Map();
  function buildV2SlotShadowSvg(fam) {
    const base = fam.replace(/[01]$/, '');
    const cached = V2_SHADOW_SVG_CACHE.get(base);
    if (cached && typeof cached.cloneNode === 'function') {
      return cached.cloneNode(true);
    }
    let spec = V2_SHADOW_DEFS[base];
    let mirrored = false;
    if (spec && spec.mirror) {
      spec = V2_SHADOW_DEFS[spec.mirror];
      mirrored = true;
    }
    if (!spec) return null;

    const uid = base;
    const isSmall = spec.vb === '0 0 48 48';
    const isTall = spec.vb === '0 0 80 160';
    const baseSw = isSmall ? 0.9 : (isTall ? 1.25 : 1.15);

    const svg = svgEl('svg', { viewBox: spec.vb, 'aria-hidden': 'true', class: 'v2-shadow-svg' });
    const defs = svgEl('defs');

    const pitGrad = svgEl('radialGradient', { id: `v2pit-${uid}`, cx: '50%', cy: '48%', r: '52%' });
    pitGrad.append(
      svgEl('stop', { offset: '0%', 'stop-color': '#c7a466', 'stop-opacity': '0.075' }),
      svgEl('stop', { offset: '68%', 'stop-color': '#8f754a', 'stop-opacity': '0.02' }),
      svgEl('stop', { offset: '100%', 'stop-color': '#000000', 'stop-opacity': '0' }),
    );

    const bodyGrad = svgEl('linearGradient', { id: `v2bod-${uid}`, x1: '0%', y1: '0%', x2: '100%', y2: '100%' });
    bodyGrad.append(
      svgEl('stop', { offset: '0%', 'stop-color': '#d2b47b', 'stop-opacity': '0.28' }),
      svgEl('stop', { offset: '55%', 'stop-color': '#8e7954', 'stop-opacity': '0.18' }),
      svgEl('stop', { offset: '100%', 'stop-color': '#423a2f', 'stop-opacity': '0.11' }),
    );

    const hiGrad = svgEl('linearGradient', { id: `v2hi-${uid}`, x1: '0%', y1: '0%', x2: '100%', y2: '100%' });
    hiGrad.append(
      svgEl('stop', { offset: '0%', 'stop-color': '#e8cd93', 'stop-opacity': '0.32' }),
      svgEl('stop', { offset: '100%', 'stop-color': '#806e50', 'stop-opacity': '0.13' }),
    );

    const darkGrad = svgEl('linearGradient', { id: `v2drk-${uid}`, x1: '0%', y1: '0%', x2: '100%', y2: '100%' });
    darkGrad.append(
      svgEl('stop', { offset: '0%', 'stop-color': '#847254', 'stop-opacity': '0.17' }),
      svgEl('stop', { offset: '100%', 'stop-color': '#352f27', 'stop-opacity': '0.09' }),
    );

    defs.append(pitGrad, bodyGrad, hiGrad, darkGrad);
    svg.append(defs);

    const rootG = svgEl('g', mirrored ? { transform: 'translate(80,0) scale(-1,1)' } : {});
    for (const p of spec.parts) {
      let attrs;
      if (p.t === 'pit') {
        attrs = { fill: `url(#v2pit-${uid})` };
      } else if (p.t === 'cast') {
        attrs = { fill: 'rgba(2, 3, 5, 0.72)' };
      } else if (p.t === 'dark') {
        attrs = {
          fill: `url(#v2drk-${uid})`,
          stroke: 'rgba(176, 148, 102, 0.20)',
          'stroke-width': baseSw * 0.85,
          'stroke-linejoin': 'round',
        };
      } else if (p.t === 'body') {
        attrs = {
          fill: `url(#v2bod-${uid})`,
          stroke: 'rgba(205, 174, 118, 0.28)',
          'stroke-width': baseSw,
          'stroke-linejoin': 'round',
        };
      } else if (p.t === 'hi') {
        attrs = {
          fill: `url(#v2hi-${uid})`,
          stroke: 'rgba(226, 196, 138, 0.30)',
          'stroke-width': baseSw * 0.85,
          'stroke-linejoin': 'round',
        };
      } else if (p.t === 'rim') {
        attrs = {
          fill: 'none',
          stroke: 'rgba(246, 222, 168, 0.42)',
          'stroke-width': baseSw * 0.85,
          'stroke-linecap': 'round',
          'stroke-linejoin': 'round',
        };
      } else if (p.t === 'cut') {
        attrs = {
          fill: 'rgba(3, 5, 8, 0.86)',
          stroke: 'rgba(182, 154, 102, 0.20)',
          'stroke-width': baseSw * 0.78,
          'stroke-linejoin': 'round',
        };
      } else if (p.t === 'rivet') {
        attrs = {
          fill: 'rgba(232, 204, 148, 0.38)',
          stroke: 'rgba(8, 10, 14, 0.76)',
          'stroke-width': baseSw * 0.55,
        };
      } else {
        attrs = {
          fill: 'none',
          stroke: 'rgba(214, 184, 126, 0.26)',
          'stroke-width': baseSw * 0.76,
          'stroke-linecap': 'round',
          'stroke-linejoin': 'round',
        };
      }
      if (p.k === 'path') attrs.d = p.d;
      else if (p.k === 'circle') { attrs.cx = p.cx; attrs.cy = p.cy; attrs.r = p.r; }
      else if (p.k === 'ellipse') { attrs.cx = p.cx; attrs.cy = p.cy; attrs.rx = p.rx; attrs.ry = p.ry; }
      else if (p.k === 'rect') { attrs.x = p.x; attrs.y = p.y; attrs.width = p.width; attrs.height = p.height; }
      rootG.append(svgEl(p.k, attrs));
    }
    svg.append(rootG);
    if (typeof svg.cloneNode === 'function') {
      V2_SHADOW_SVG_CACHE.set(base, svg.cloneNode(true));
    }
    return svg;
  }

  function makeV2EmptyTile(fam) {
    const tile = el('span', 'worntile is-v2-glyph');
    tile.dataset.shadowFam = fam.replace(/[01]$/, '');
    const ico = buildV2SlotShadowSvg(fam);
    if (!ico) {
      tile.textContent = '◇';
      return tile;
    }
    tile.append(ico);
    return tile;
  }

  function buildWeaponSetTooltipSpec(entity, setIdx, l) {
    ensureWeaponPresets(entity);
    const roman = setIdx === 1 ? 'II' : 'I';
    const isActive = entity.activeWeaponSet === setIdx;
    const isRu = STAND_STATE.lang === 'ru';
    const setObj = entity.weaponPresets[setIdx] || { rhand: null, lhand: null };
    const rIt = setObj.rhand && entity.items.includes(setObj.rhand) ? setObj.rhand : null;
    const lIt = setObj.lhand && entity.items.includes(setObj.lhand) ? setObj.lhand : null;
    const stateTone = isActive ? 'ok' : 'neutral';
    const stateText = isActive
      ? (isRu ? 'Активный пресет — свойства и урон применяются' : 'Active set — stats and damage apply')
      : (isRu ? 'Неактивный пресет — в резерве (0 бонусов, скрыто из рюкзака)' : 'Inactive reserve — 0 bonuses, hidden from pack');
    return {
      title: `${l.ui.weaponSetLabel} ${roman}`,
      rows: [
        {
          kind: 'cards',
          items: [
            { label: l.slots.rhand, value: rIt ? itemName(rIt) : l.ui.emptySetSlot, tone: rIt ? stateTone : 'neutral' },
            { label: l.slots.lhand, value: lIt ? itemName(lIt) : l.ui.emptySetSlot, tone: lIt ? stateTone : 'neutral' },
          ],
        },
        { kind: 'sep' },
        { kind: 'line', tone: isActive ? 'gold' : 'muted', text: stateText },
        { kind: 'line', tone: 'muted', text: l.ui.weaponSetTip.replace('{n}', roman) },
      ],
    };
  }

  function buildWeaponPresetTabs(entity, l) {
    ensureWeaponPresets(entity);
    const tabs = el('div', 'v2-wep-tabs');
    tabs.setAttribute('role', 'group');
    tabs.setAttribute('aria-label', l.ui.weaponSetLabel);
    [0, 1].forEach((idx) => {
      const roman = idx === 1 ? 'II' : 'I';
      const active = entity.activeWeaponSet === idx;
      const setObj = entity.weaponPresets[idx] || {};
      const hasGear = !!(setObj.rhand || setObj.lhand);
      const btn = el('button', `v2-wep-tab${active ? ' on' : ''}${hasGear ? ' has-gear' : ''}`, roman);
      btn.type = 'button';
      btn.dataset.setIdx = String(idx);
      btn.setAttribute('aria-pressed', String(active));
      btn.setAttribute('aria-label', `${l.ui.weaponSetLabel} ${roman}`);
      attachPlaqueTooltip(btn, () => buildWeaponSetTooltipSpec(entity, idx, l));
      btn.onclick = (e) => {
        e.stopPropagation();
        switchWeaponPreset(entity, idx);
        repaint();
      };
      tabs.append(btn);
    });
    return tabs;
  }

  function buildV2SetRail(entity, l) {
    const sets = activeSets(entity);
    if (!sets.length) {
      prevActiveRelics.clear();
      return null;
    }

    const rail = el('div', 'v2-setrail');
    rail.setAttribute('role', 'group');
    rail.setAttribute('aria-label', l.ui.setBonuses || 'Set bonuses');

    let iconScale = 0.78;
    if (sets.length > 9) {
      rail.classList.add('is-dense-2col');
      iconScale = 0.54;
    } else if (sets.length > 7) {
      rail.classList.add('is-compact');
      iconScale = 0.60;
    } else if (sets.length > 5) {
      rail.classList.add('is-compact');
      iconScale = 0.68;
    }
    rail.style.setProperty('--relic-scale', String(iconScale));

    const rt = getEmbeddedRelicRt();
    const nextRelics = new Map();

    sets.forEach((s, idx) => {
      const isDormant = !s.activeTier;
      const btn = el('button', `v2-relic-btn${isDormant ? ' is-dormant' : ' is-active'}`);
      btn.type = 'button';
      btn.dataset.set = s.id;
      btn.dataset.stage = String(s.stage);
      btn.dataset.dormant = isDormant ? '1' : '0';
      btn.style.setProperty('--orb-i', String(idx));
      applySetVars(btn, s.def.colour);

      const stName = setStageLabel(s.id, s.stage, s.stageName, l);
      const setName = STAND_STATE.lang === 'ru' ? s.def.ru : s.def.en;
      btn.setAttribute('aria-label', `${setName} ${s.count}/${s.def.pieces} (${stName})`);

      const host = el('span', 'v2-relic-host');
      btn.append(host);

      const rec = rt ? rt.mountRelic(s.id, host, {
        tileEl: btn,
        stage: s.stage,
        dormant: isDormant,
        iconScale,
      }) : null;

      const prev = prevActiveRelics.get(s.id);
      if (rec && !isDormant && (!prev || prev.dormant || s.stage > prev.stage)) {
        rt.triggerSpawnRecord(rec, idx * 28);
      }
      nextRelics.set(s.id, { dormant: isDormant, stage: s.stage });

      attachSetRelicTooltip(btn, s, rec, rt);
      btn.onclick = (e) => {
        e.stopPropagation();
        if (rec && !isDormant && rt) rt.triggerSpawnRecord(rec, 0);
        STAND_STATE.selectedItem = s.worn[0] || null;
        STAND_STATE.selectedSide = 'local';
        repaint();
      };
      rail.append(btn);
    });

    prevActiveRelics = nextRelics;
    return rail;
  }

