  function evalClassicSpell(spec, level) {
    const L = Math.max(1, Math.trunc(Number(level) || 1));
    const dur = spec.dur ? spec.dur[0] + spec.dur[1] * Math.max(1, Math.floor(L / Math.max(1, spec.dur[2] || 1))) : null;
    const ch = spec.ch ? Math.min(spec.ch[3] ?? 100, spec.ch[0] + spec.ch[1] * Math.floor(L / Math.max(1, spec.ch[2] || 1))) : null;
    const lo = spec.mag ? spec.mag[0] + spec.mag[2] * L : null;
    const hi = spec.mag ? spec.mag[1] + spec.mag[3] * L : null;
    return { L, dur, ch, lo, hi };
  }

